'use strict';
const researchResults=new Map(),researchSources=['sec','awards','policy','bills','earnings'];
const sourceNames={sec:'Corporate insiders Â· SEC',awards:'Contracts & grants',policy:'Regulatory policy',bills:'Bills & committees',earnings:'Earnings',agent:'Research leads',signals:'Connected buying'};
let researchFilter='confirmed',researchWindow=90,treasuryResult=null,researchStatus=null;
const SECTORS={XLK:'Technology',XLC:'Communication',XLY:'Consumer discretionary',XLP:'Consumer staples',XLI:'Industrials',XLE:'Energy',XLF:'Financials',XLV:'Healthcare',XLU:'Utilities',XLRE:'Real estate',XLB:'Materials'};
const SECTOR_DEFAULT={INTC:'XLK',NVDA:'XLK',AMD:'XLK',AAPL:'XLK',MSFT:'XLK',AVGO:'XLK',BE:'XLI',LMT:'XLI',RTX:'XLI',TSLA:'XLY',AMZN:'XLY',GOOG:'XLC',GOOGL:'XLC',META:'XLC',PLTR:'XLK'};
let sectorChoices=read('poor-sector-comparisons',{}),riskPlans=read('poor-risk-plans',{}),riskSymbol=null;
function researchLink(url,label){try{const u=new URL(url);return u.protocol==='https:'?`<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:esc(label)}catch{return esc(label)}}
function researchDate(s){return s?date(s.slice(0,10)):'Not supplied'}
async function ensureResearch(){const symbol=marketSymbol;if(!tickerValid(symbol))return;
 const missing=researchSources.concat('agent').filter(source=>{const r=researchResults.get(symbol+':'+source);return !r||(!r.loading&&Date.now()-r.loadedAt>15*60000)});if(!missing.length){renderResearch();return}
 await Promise.allSettled(missing.map(async source=>{const key=symbol+':'+source;researchResults.set(key,{loading:true});renderResearch();try{const r=await getLiveJSON('/api/research'+(source==='agent'?'/agent':'')+'?symbol='+symbol+'&source='+source);researchResults.set(key,{...r,loadedAt:Date.now()})}catch{researchResults.set(key,{error:'Source temporarily unavailable',loadedAt:Date.now()})}renderResearch()}));
 try{const result=await getLiveJSON('/api/research/signals?symbol='+symbol);researchResults.set(symbol+':signals',{value:result,loadedAt:Date.now()})}catch{researchResults.set(symbol+':signals',{error:'Connections unavailable'})}renderResearch();
}
function sourceValue(source){const r=researchResults.get(marketSymbol+':'+source);return r?.value||r}
function renderResearch(){if(!$('#researchTimeline'))return;
 $('#researchSymbol').textContent=marketSymbol;const cutoff=new Date(Date.now()-researchWindow*86400000).toISOString().slice(0,10);
 const sourceState=researchSources.concat('agent').map(source=>{const r=researchResults.get(marketSymbol+':'+source),v=r?.value||r;const count=v?.items?.length;return `<span class="source-state ${r?.error||r?.stale||v?.unavailable||v?.partial?'source-warning':''}" title="${esc(dateText(v?.coverage||r?.error||'Connecting'))}">${sourceNames[source]}: ${r?.loading||!r?'loading':v?.unavailable?'key needed':r?.error?'unavailable'+(count?' Â· saved data':''):r?.stale?'saved Â· stale':v?.partial?'partial Â· '+count+' records':count===undefined?'unavailable':count+' records'}</span>`});$('#researchSources').innerHTML=sourceState.join('');
 const political=stockRecords().filter(r=>r.type==='Purchase').map(r=>({id:r.id,kind:'political',title:r.person+' Â· '+r.owner,traded:r.traded,published:disclosedDate(r),firstObserved:r.firstObserved,amount:r.amount,url:r.source,match:r.quality||'Public disclosure',note:r.asset+' Â· '+r.notes,original:r}));
 const all=[...political,...researchSources.concat('agent').flatMap(s=>sourceValue(s)?.items||[])];
 const items=[...new Map(all.map(i=>[i.id||i.url+'|'+i.title,i])).values()].filter(i=>(i.published||i.traded||i.firstObserved||'').slice(0,10)>=cutoff).filter(i=>researchFilter==='all'||researchFilter==='confirmed'&&(i.kind==='political'||i.kind==='insider'||i.kind==='award'&&i.exact)||i.kind===researchFilter).sort((a,b)=>(b.published||b.firstObserved||b.traded||'').localeCompare(a.published||a.firstObserved||a.traded||''));
 $('#researchTimeline').innerHTML=items.slice(0,60).map(i=>{const ret=i.original?disclosureReturn(i.original):i.purchase&&i.published&&PRICES[marketSymbol]?.closes?.[i.published.slice(0,10)]?{pct:(PRICES[marketSymbol].latest/PRICES[marketSymbol].closes[i.published.slice(0,10)]-1)*100}:null;return `<tr><td><b>${researchLink(i.url,i.title)}</b><small>${esc(i.kind==='insider'?i.note:i.kind==='political'?'Political purchase':i.awardKind||i.documentType||i.kind)}</small><details><summary>Evidence</summary><p>${esc(i.summary||i.description||i.note||'')}</p>${i.role?'<p>'+esc(i.role)+'</p>':''}${i.committees?.length?'<p>Referred to: '+esc(i.committees.join(', '))+'</p>':''}${i.plan10b51?'<p>10b5-1 plan indicated</p>':''}<p>${esc(i.match||'')} Â· ${esc(i.agency||'')}</p><p>First observed: ${i.firstObserved?esc(stamp(i.firstObserved)):'Not recorded for legacy political rows'}</p></details></td><td>${researchDate(i.traded)}<small>${i.kind==='policy'?'Effective date':i.kind==='award'?'Award start':i.kind==='earnings'?'Expected report':'Event / trade'}</small></td><td>${researchDate(i.published)}<small>${i.published?.includes('T')?esc(stamp(i.published)):'Public date; time unknown'}</small></td><td>${typeof i.amount==='number'?money(i.amount):esc(i.amount||'â€”')}<small>${i.kind==='award'?'Obligations':i.kind==='insider'?(i.shares??'â€”')+' shares':'Reported bracket'}</small></td><td class="${ret?ret.pct>=0?'gain':'loss':''}">${ret?signed(ret.pct):'â€”'}<small>${ret?'Since public-day close':'No comparable return'}</small></td></tr>`}).join('')||'<tr><td colspan="5" class="empty">No matching evidence in this window. Check source status above.</td></tr>';
 const signals=sourceValue('signals');$('#connectedSignals').innerHTML=(signals?.items||[]).slice(0,3).map(s=>`<div class="connection"><strong>${s.politicians.length} political household${s.politicians.length===1?'':'s'}${s.insiderOwners?' + '+s.insiderOwners+' SEC owner'+(s.insiderOwners===1?'':'s'):''}</strong><span>${esc(s.politicians.join(', '))} Â· ${researchDate(s.start)}â€“${researchDate(s.end)}</span><small>All filings public by ${researchDate(s.publicBy)} Â· poor observed ${researchDate(s.firstObserved)}</small><div>${s.forward.map(f=>`<span>${f.sessions}d: ${f.return===undefined?'collecting':signed(f.return)}${f.excess!==null&&f.excess!==undefined?' Â· vs SPY '+(f.excess>=0?'+':'')+f.excess.toFixed(2)+' pp':''}</span>`).join(' Â· ')}</div></div>`).join('')||'<p class="muted">No qualifying buying combination in the loaded sources. Forward tracking starts when poor first observes one.</p>';
 $('#connectionCoverage').textContent=(signals?.inputsCurrent===false?'Some inputs are stale or unavailable; new signals paused. ':'')+(signals?.coverage||'30-day trade windows; source dates remain visible.');
 $('#researchCoverage').innerHTML=researchSources.map(s=>`<p><b>${sourceNames[s]}:</b> ${esc(sourceValue(s)?.coverage||'Waiting for source')}</p>`).join('')+'<p>First-observed timestamps begin with this release. Public-day return is a close-price comparison, not an executable entry or realized profit. Option returns are underlying-stock changes. Regulatory and award candidates are not included in buying counts. Reposts and Research summaries never count as additional buyers.</p>';
 renderEarnings();
}
function renderEarnings(){const r=sourceValue('earnings'),event=r?.items?.[0],el=$('#earningsWarning');if(!el)return;if(event){const days=Math.ceil((Date.parse(event.traded)-Date.now())/86400000),h=swingHorizon==='short'?30:100;el.className='earnings-warning'+(days<=h?' earnings-soon':'');el.innerHTML=`<b>Expected earnings ${researchDate(event.traded)} Â· ${days===0?'today':days+' days'}</b> Â· ${days<=h?'Inside your holding horizon. ':''}${researchLink(event.url,'Calendar source')} Â· Confirm with investor relations; time unknown.`}else{el.className='earnings-warning';el.textContent=r?.coverage||'Checking earnings calendarâ€¦'}}
function renderTreasury(){if(!$('#treasuryYields'))return;const r=treasuryResult,rows=r?.value?.rows,a=rows?.at(-1),b=rows?.at(-6);$('#treasuryYields').innerHTML=a?`<span><b>US Treasury yields</b><small>${researchDate(a.date)}${r.stale?' Â· stale':''}</small></span>`+[['m3','3m'],['y2','2y'],['y10','10y'],['y30','30y']].map(([k,label])=>`<span><b>${label} ${a[k]===null?'â€”':a[k].toFixed(2)+'%'}</b><small>${b&&a[k]!==null&&b[k]!==null?((a[k]-b[k])*100>=0?'+':'')+((a[k]-b[k])*100).toFixed(0)+' bp / 5 sessions':'5-session change unavailable'}</small></span>`).join('')+`<span><b>10y âˆ’ 2y ${a.y2!==null?((a.y10-a.y2)*100).toFixed(0)+' bp':'â€”'}</b><small>${researchLink(r.value.url,'Treasury source')}</small></span>`:'<span>US Treasury yields unavailable Â· retry on next refresh</span>';
 const c=researchStatus?.collector,overdue=c&&Date.now()-Date.parse(c.lastRun)>8*3600000;
 $('#collectorStatus').innerHTML=c?`<b>${overdue?'Research overdue':'Research refresh'}: ${esc(stamp(c.lastRun))}</b> · ${c.successful} checks passed / ${c.failed} failed or unconnected · every 6h while this PC is awake and signed in<br><b>Research fallback:</b> ${esc(c.fallbackStatus||'Not yet run')} · ${esc(c.agentStatus||'')}<details><summary>Source health & maintenance${overdue?' · collector overdue':''}</summary>${overdue?'<p>No completed run in over 8 hours. Check the PC and scheduled collector.</p>':''}${(c.issues||[]).map(i=>`<p>${esc(i.path)} · ${esc(i.reason)}</p>`).join('')||'<p>No source issues reported by the last completed run.</p>'}<p>Fallback leads never replace prices, verified transactions or calculated performance. Annual portfolio estimates and roster changes still require review.</p></details>`:'Scheduled collector not yet reporting. Feeds refresh when the app is open.';
}
async function refreshResearchMacro(){await Promise.allSettled([getLiveJSON('/api/research/treasury').then(r=>treasuryResult=r),getLiveJSON('/api/research/status').then(r=>researchStatus=r)]);renderTreasury()}
function sectorSymbol(){return sectorChoices[marketSymbol]||SECTOR_DEFAULT[marketSymbol]||''}
function renderSector(){const s=sectorSymbol();$('#sectorSelect').value=s;const n=swingHorizon==='short'?20:60,p=PRICES[marketSymbol],q=PRICES[s],r=relativeReturn(p,q,n);$('#sectorResult').textContent=s?`${n} sessions vs ${s}: ${r===null?'history unavailable':(r>=0?'+':'')+r.toFixed(2)+' percentage points'} Â· ${q?.asOf?date(q.asOf):'loading'} Â· ${sectorChoices[marketSymbol]?'your comparison':'default comparison, editable'}`:'Choose a sector ETF to compare matched closing dates.'}
async function updateSector(){const s=sectorSymbol();renderSector();if(s&&!PRICES[s]){await loadMarketPrices([s]);renderSector()}}
function calculatePosition({entry,stop,target,risk,capital,direction='long'}){const values=[entry,stop,target,risk,capital];if(values.some(v=>!Number.isFinite(v)||v<=0))return {error:'Enter positive entry, stop, target, risk budget and maximum position value.'};const perShare=direction==='short'?stop-entry:entry-stop,reward=direction==='short'?entry-target:target-entry;if(perShare<=0||reward<=0)return {error:direction==='short'?'Short trade: stop must be above entry and target below.':'Long trade: stop must be below entry and target above.'};const shares=Math.floor(Math.min(risk/perShare,capital/entry));return {shares,notional:shares*entry,loss:shares*perShare,profit:shares*reward,rr:reward/perShare}}
function renderRisk(){if(riskSymbol!==marketSymbol){riskSymbol=marketSymbol;const saved=riskPlans[marketSymbol]||{};for(const k of ['entry','stop','target','risk','capital'])$('#risk-'+k).value=saved[k]||'';$('#risk-direction').value=saved.direction||'long'}const plan={direction:$('#risk-direction').value};for(const k of ['entry','stop','target','risk','capital'])plan[k]=Number($('#risk-'+k).value);const result=calculatePosition(plan);$('#riskCurrency').textContent=PRICES[marketSymbol]?.currency||'Quote currency';$('#riskResult').textContent=result.error||`${result.shares} shares Â· value ${money(result.notional,PRICES[marketSymbol]?.currency||'USD')} Â· planned loss ${money(result.loss,PRICES[marketSymbol]?.currency||'USD')} Â· target gain ${money(result.profit,PRICES[marketSymbol]?.currency||'USD')} Â· reward / risk ${result.rr.toFixed(2)}Ã—`;return plan}
function renderResearchTools(){if(!$('#researchTimeline'))return;renderResearch();updateSector();renderRisk();if(view==='market')ensureResearch()}
if(typeof window!=='undefined'){
 $('#researchFilter').onchange=e=>{researchFilter=e.target.value;renderResearch()};$('#researchWindow').onchange=e=>{researchWindow=Number(e.target.value);renderResearch()};
 $('#sectorSelect').innerHTML='<option value="">Choose comparison</option>'+Object.entries(SECTORS).map(([s,n])=>`<option value="${s}">${s} Â· ${n}</option>`).join('');$('#sectorSelect').onchange=e=>{sectorChoices[marketSymbol]=e.target.value;persist('poor-sector-comparisons',sectorChoices);updateSector()};
 $('#riskForm').oninput=()=>{riskPlans[marketSymbol]=renderRisk();persist('poor-risk-plans',riskPlans)};$('#riskUseClose').onclick=()=>{if(PRICES[marketSymbol]){$('#risk-entry').value=PRICES[marketSymbol].latest.toFixed(2);riskPlans[marketSymbol]=renderRisk();persist('poor-risk-plans',riskPlans)}};
 refreshResearchMacro();renderResearchTools();setInterval(()=>{if(!document.hidden){refreshResearchMacro();if(view==='market')ensureResearch()}},15*60000);
}
